<?php require 'includes/auth.php'; $_SESSION['cart']=$_SESSION['cart']??[]; if($_SERVER['REQUEST_METHOD']==='POST'){ $act=$_POST['action']; $id=(int)$_POST['id']; if($act==='add')$_SESSION['cart'][$id]=($_SESSION['cart'][$id]??0)+max(1,(int)($_POST['qty']??1)); if($act==='remove')unset($_SESSION['cart'][$id]); if($act==='update')foreach($_POST['qtys']??[] as $i=>$n){if((int)$n>0)$_SESSION['cart'][(int)$i]=(int)$n;else unset($_SESSION['cart'][(int)$i]);} header('Location: cart.php');exit;} $items=[];$total=0;if($_SESSION['cart']){$in=implode(',',array_fill(0,count($_SESSION['cart']),'?'));$s=$pdo->prepare("SELECT * FROM products WHERE id IN ($in)");$s->execute(array_keys($_SESSION['cart']));foreach($s as $p){$p['qty']=$_SESSION['cart'][$p['id']];$p['sub']=$p['qty']*$p['price'];$total+=$p['sub'];$items[]=$p;}}?>
